// Java's question is monomorphism, not inlining. The JIT inlines a virtual
// call only while the call site has observed ONE receiver type; at three or
// more (megamorphic) it falls back to vtable dispatch and no amount of making
// the callee smaller helps.
static int step(int x) { return x < 0 ? 0 : x; }   // small: inlined if hot and monomorphic

// make a megamorphic site monomorphic instead of asking for inlining:
if (value instanceof Integer iv) { total += step(iv); }
else if (value instanceof String sv) { total += step(sv.length()); }
